#!/usr/bin/env node
/* validate-pattern-registry.js — structural guard for the pattern vocabulary.
 *
 * OWNERSHIP (D25, 2026-08-26): pattern_registry.json is the HAND-MAINTAINED
 * source of truth. It was originally generated by build-pattern-registry.js,
 * but by 2026-08-26 hand curation had advanced it far past the script's
 * tables (38 V2 records, 171 backfilled fields, 52 verified names), so the
 * ownership was formally flipped: edit the registry directly; the builder is
 * demoted to an incremental scanner (report / --append missing ids only, no
 * regeneration — its --write refuses).
 *
 * Written because the registry was silently reverted (2026-07-31: 59 records
 * became 50, all 10 categories vanished, `system` and `member_of` went to
 * zero) and every existing validator passed, because none of them look at
 * this file. A hand-maintained file is still one bad merge away from the
 * same rollback, so the guard stays.
 *
 * These floors are deliberately absolute rather than relative. A check that
 * only compares against the current file cannot notice the file itself being
 * rolled back. Raise them when the vocabulary legitimately grows.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const REGISTRY = path.join(ROOT, 'data/pathology/pattern_registry.json');

// Floors raised to the measured 2026-08-26 state (D25) — the registry now
// holds the Pattern V2 hand curation and the floors lock it in. Raise
// deliberately; never lower to make a run pass.
const MIN_RECORDS = 151;
// D24 (2026-08-26): the ten family heads were promoted level=category →
// level=pattern (their clinical cards are real diagnoses). The taxonomy axis
// SURVIVES the promotion — what this file guards is no longer "10 records
// with level=category" but "10 family heads that still carry members". A
// promotion must never quietly dissolve the two-axis structure.
const MIN_FAMILY_HEADS = 10;
const MIN_WITH_SYSTEM = 151;
const MIN_WITH_MEMBER_OF = 53;
const REQUIRED_FAMILY_HEADS = [
  'pattern.kidney_deficiency', 'pattern.blood_deficiency', 'pattern.qi_deficiency',
  'pattern.yin_deficiency', 'pattern.yang_deficiency',
  'pattern.fire', 'pattern.heat', 'pattern.damp_heat', 'pattern.phlegm', 'pattern.wind_external',
];

function main() {
  const records = JSON.parse(fs.readFileSync(REGISTRY, 'utf8')).records || [];
  const ids = new Set(records.map((r) => r.id));
  const familyHeads = records.filter((r) => (r.members || []).length);
  const withSystem = records.filter((r) => r.system);
  const withMemberOf = records.filter((r) => (r.member_of || []).length);

  const defects = [];
  const floor = (label, actual, min, hint) => {
    if (actual < min) defects.push(`P1 ${label}: ${actual} < 下限 ${min} —— ${hint}`);
  };

  floor('證型筆數', records.length, MIN_RECORDS, '登錄檔疑似被舊版腳本覆蓋');
  floor('家族父節點數', familyHeads.length, MIN_FAMILY_HEADS, '兩軸家族結構遺失');
  floor('有 system 的筆數', withSystem.length, MIN_WITH_SYSTEM, '辨證體系維度遺失');
  floor('有 member_of 的筆數', withMemberOf.length, MIN_WITH_MEMBER_OF, '兩軸歸屬遺失');

  REQUIRED_FAMILY_HEADS.forEach((id) => {
    if (!ids.has(id)) defects.push(`P2 缺少家族父節點 ${id}`);
    else if (!familyHeads.some((c) => c.id === id)) defects.push(`P2 ${id} 存在但 members 空了 —— D24 升格保留家族結構,不得順手拆掉`);
  });

  // P3 — every membership must resolve, in both directions
  familyHeads.forEach((c) => (c.members || []).forEach((m) => {
    if (!ids.has(m)) defects.push(`P3 ${c.id} 的成員 ${m} 不存在`);
  }));
  records.forEach((r) => (r.member_of || []).forEach((p) => {
    if (!ids.has(p)) defects.push(`P3 ${r.id} 的 member_of 指向不存在的 ${p}`);
    else {
      const cat = records.find((x) => x.id === p);
      if (cat && !(cat.members || []).includes(r.id)) {
        defects.push(`P3 ${r.id} 宣稱屬於 ${p},但 ${p} 的 members 沒有它（雙向不一致）`);
      }
    }
  }));
  records.forEach((r) => (r.develops_into || []).forEach((d) => {
    if (!ids.has(d)) defects.push(`P3 ${r.id}.develops_into 指向不存在的 ${d}`);
  }));

  console.log('===== 證型登錄檔結構檢查 =====\n');
  console.log(`證型筆數        ${records.length}  (下限 ${MIN_RECORDS})`);
  console.log(`家族父節點      ${familyHeads.length}  (下限 ${MIN_FAMILY_HEADS})`);
  console.log(`有辨證體系      ${withSystem.length}  (下限 ${MIN_WITH_SYSTEM})`);
  console.log(`有兩軸歸屬      ${withMemberOf.length}  (下限 ${MIN_WITH_MEMBER_OF})`);
  console.log(`待補中文名      ${records.filter((r) => r.needs_name_zh).length}`);
  console.log(`待補辨證體系    ${records.filter((r) => r.needs_system).length}`);

  if (defects.length) {
    console.log(`\n❌ ${defects.length} 個問題:\n`);
    defects.forEach((d) => console.log('  ' + d));
    console.log('\n⚠️ 修法(D25):pattern_registry.json 是手工維護的正本——直接編輯它,');
    console.log('   或從 git 歷史還原被洗掉的內容,然後重跑本驗證器。');
    console.log('   build-pattern-registry.js 已降級為增量偵測工具(--write 會拒絕執行),');
    console.log('   只有「已引用但未登錄」的缺漏可用它 --append 補骨架。');
    process.exitCode = 1;
  } else {
    console.log('\nvalidate-pattern-registry: PASS');
  }
}

main();
